// Mock v2 – single-restaurant online ordering, guest checkout only (no accounts).
// Menu, cart and checkout form; after submitting, the order continues on its own page (order.js).
// illustrations are generated by tools/dishes.mjs; a product can point to a real photo with `img`
const dishImg = p => p.img ?? `img/dishes/${p.id}.svg`;

const state = {
  cart: store.get('v2_cart', []),         // [{ pid, variant, qty }]
  fulfilment: store.get('v2_fulfilment', 'delivery'),
};
const save = () => { store.set('v2_cart', state.cart); store.set('v2_fulfilment', state.fulfilment); };

/* ---------- time / opening hours ---------- */
const toMin = hhmm => { const [h, m] = hhmm.split(':').map(Number); return h * 60 + m; };
const fmt = min => `${String(Math.floor(min / 60)).padStart(2, '0')}:${String(min % 60).padStart(2, '0')}`;
const etaMin = eta => parseInt(eta, 10);
const OPEN = toMin(R.hours.open), CLOSE = toMin(R.hours.close);
const nowMin = () => { const d = new Date(); return d.getHours() * 60 + d.getMinutes(); };
const isOpen = () => { const n = nowMin(); return n >= OPEN && n < CLOSE; };
function timeSlots() {
  const lead = etaMin(state.fulfilment === 'delivery' ? R.delivery.eta : R.pickup.eta);
  let start = Math.max(nowMin(), OPEN) + lead;
  start = Math.ceil(start / 15) * 15;
  const slots = [];
  for (let t = start; t <= CLOSE; t += 15) slots.push(t);
  return slots;
}

/* ---------- cart math ---------- */
const lineKey = l => `${l.pid}|${l.variant ?? ''}`;
const subtotal = () => state.cart.reduce((s, l) => s + byId(l.pid).price * l.qty, 0);
const count = () => state.cart.reduce((s, l) => s + l.qty, 0);
const deliveryFee = () => (state.fulfilment === 'delivery' && state.cart.length ? R.delivery.fee : 0);
const total = () => subtotal() + deliveryFee();
const minMissing = () => (state.fulfilment === 'delivery' ? Math.max(0, R.delivery.minOrder - subtotal()) : 0);
const hasAlcohol = () => state.cart.some(l => byId(l.pid).alcohol);

function addToCart(pid, variant = null, qty = 1) {
  const key = lineKey({ pid, variant });
  const line = state.cart.find(l => lineKey(l) === key);
  if (line) line.qty += qty; else state.cart.push({ pid, variant, qty });
  save(); renderCart(); renderMenuQty(); bumpCartBar();
}
function changeQty(key, d) {
  const line = state.cart.find(l => lineKey(l) === key);
  if (!line) return;
  line.qty += d;
  if (line.qty <= 0) state.cart = state.cart.filter(l => l !== line);
  save(); renderCart(); renderMenuQty();
}

/* ---------- header ---------- */
function renderHeader() {
  document.title = t('meta.title', { name: R.name });
  $('#rLogo').textContent = R.logo;
  $('#rName').textContent = R.name;
  $('#rTagline').textContent = R.tagline;
  $('#rAddress').textContent = `${R.address.street}, ${R.address.city}`;
  $('#rHours').textContent = t('hours.daily', R.hours);
  $('#rDeliveryFee').textContent = t('hdr.delivery', { fee: zl(R.delivery.fee) });
  $('#rDeliveryMin').textContent = t('hdr.min', { amount: zl(R.delivery.minOrder) });
  $('#rDeliveryEta').textContent = eta(R.delivery.eta);
  $('#rPickupEta').textContent = t('hdr.pickup', { eta: eta(R.pickup.eta) });
  $('#fName').textContent = `${R.name} · ${R.address.street}, ${R.address.city}`;
  const open = isOpen();
  const st = $('#rStatus');
  st.className = 'fact fact--status' + (open ? '' : ' is-closed');
  st.innerHTML = `<span class="fact__dot"></span><div><strong>${t(open ? 'hdr.open' : 'hdr.closed')}</strong><small>${
    open ? t('hdr.until', { time: R.hours.close }) : t(nowMin() < OPEN ? 'hdr.from' : 'hdr.tomorrow', { time: R.hours.open })}</small></div>`;
}

// today's order stays one tap away – its page is otherwise only linked from the SMS / e-mail
function renderOrderLink() {
  const today = new Date().toDateString();
  const o = orders.all()
    .filter(o => isPlaced(o) && new Date(placedAt(o)).toDateString() === today)
    .sort((a, b) => b.createdAt - a.createdAt)[0];
  $('#orderLink').hidden = !o;
  if (!o) return;
  $('#orderLink').href = orderUrl(o);
  $('#orderLink').innerHTML = `<span class="container"><span>✓ ${t('orderlink', { no: `<strong>${o.no}</strong>` })}</span><span class="order-link__go">${t('orderlink.view')}</span></span>`;
}

/* ---------- language ---------- */
function setLang(code) {
  switchLang(code);
  renderHeader(); renderOrderLink(); renderMenu(); setupScrollSpy(); renderCart();
  if (!$('#checkout').hidden) renderCheckout();
}

/* ---------- menu ---------- */
function tags(p) {
  return (p.veg ? `<span class="tag tag--veg">${t('tag.veg')}</span>` : '')
    + (p.spicy ? `<span class="tag tag--spicy">${t('tag.spicy')}</span>` : '')
    + (p.alcohol ? '<span class="tag tag--18">18+</span>' : '');
}
function renderMenu() {
  $('#catsInner').innerHTML = CATEGORIES.map(c => `<a href="#cat-${c.id}" data-cat="${c.id}">${c.icon} ${nameOf(c)}</a>`).join('');
  $('#menu').innerHTML = CATEGORIES.map(c => `
    <section class="cat" id="cat-${c.id}">
      <h2 class="cat__title">${c.icon} ${nameOf(c)} <span class="cat__en">${altNameOf(c)}</span></h2>
      ${c.desc ? `<p class="cat__desc">${tx(c.desc)}</p>` : ''}
      <div class="items">
        ${PRODUCTS.filter(p => p.cat === c.id).map(p => `
          <article class="item" data-pid="${p.id}">
            <div class="item__body">
              <h3 class="item__name">${nameOf(p)}${tags(p)}</h3>
              ${altNameOf(p) ? `<p class="item__en">${altNameOf(p)}</p>` : ''}
              ${p.desc ? `<p class="item__desc">${tx(p.desc)}</p>` : ''}
              <p class="item__price">${zl(p.price)}${p.variants ? `<span> · ${t('item.choice')}</span>` : ''}</p>
            </div>
            <div class="item__media">
              <img src="${dishImg(p)}" alt="" width="200" height="200" loading="lazy" decoding="async">
              <div class="item__ctl"></div>
            </div>
          </article>`).join('')}
      </div>
    </section>`).join('');
  renderMenuQty();
}
// simple products get an inline − qty + stepper; products with variants keep "+" (opens the picker) and a count badge
const ICON_PLUS = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg>';
const ICON_MINUS = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14"/></svg>';
function renderMenuQty() {
  $$('.item').forEach(el => {
    const p = byId(el.dataset.pid);
    const q = state.cart.filter(l => l.pid === p.id).reduce((s, l) => s + l.qty, 0);
    el.classList.toggle('is-in-cart', q > 0);
    const name = { name: nameOf(p) };
    const html = q && !p.variants
      ? `<div class="step"><button data-step="-1" aria-label="${t('item.remove_one', name)}">${ICON_MINUS}</button><span>${q}</span><button data-step="1" aria-label="${t('item.add_one', name)}">${ICON_PLUS}</button></div>`
      : `<button class="add" data-add aria-label="${t('item.add', name)}">${ICON_PLUS}${q ? `<span class="add__badge">${q}</span>` : ''}</button>`;
    const ctl = $('.item__ctl', el);
    if (ctl.innerHTML !== html) ctl.innerHTML = html;
  });
}
function bumpCartBar() {
  const b = $('#cartBar');
  b.classList.remove('is-bump'); void b.offsetWidth; b.classList.add('is-bump');
}
let spy = null;
function setupScrollSpy() {
  spy?.disconnect();                              // the menu is re-rendered on language change
  const bar = $('#catsInner'), links = $$('a', bar);
  const obs = spy = new IntersectionObserver(entries => {
    entries.forEach(e => {
      if (!e.isIntersecting) return;
      const id = e.target.id.slice(4);
      links.forEach(a => a.classList.toggle('is-active', a.dataset.cat === id));
      // scroll only the chip bar horizontally – scrollIntoView() would also scroll the page and fight the user's scroll
      const a = links.find(l => l.dataset.cat === id);
      const x = a.getBoundingClientRect().left - bar.getBoundingClientRect().left + bar.scrollLeft;
      bar.scrollTo({ left: x - (bar.clientWidth - a.offsetWidth) / 2, behavior: 'smooth' });
    });
  }, { rootMargin: '-140px 0px -65% 0px' });
  $$('.cat').forEach(s => obs.observe(s));
}

/* ---------- cart ---------- */
function renderFulfilment() {
  $$('#fulfilment button, #coFulfilment button').forEach(b => b.classList.toggle('is-active', b.dataset.f === state.fulfilment));
}
function renderCart() {
  renderFulfilment();
  const items = $('#cartItems');
  if (!state.cart.length) {
    items.innerHTML = `<div class="cart__empty"><span>🥡</span>${t('cart.empty')}</div>`;
  } else {
    items.innerHTML = state.cart.map(l => {
      const p = byId(l.pid), key = lineKey(l);
      return `<div class="line">
        <div><div class="line__name">${nameOf(p)}</div>${l.variant ? `<div class="line__variant">${variantName(l)}</div>` : ''}</div>
        <div class="line__price">${zl(p.price * l.qty)}</div>
        <div class="qty"><button data-key="${key}" data-d="-1" aria-label="${t('qty.less')}">${ICON_MINUS}</button><span>${l.qty}</span><button data-key="${key}" data-d="1" aria-label="${t('qty.more')}">${ICON_PLUS}</button></div>
      </div>`;
    }).join('');
  }
  const missing = minMissing();
  const canOrder = state.cart.length && !missing && timeSlots().length;
  $('#cartFoot').innerHTML = `
    <div class="row"><span>${t('cart.subtotal')}</span><span>${zl(subtotal())}</span></div>
    ${deliveryFee() ? `<div class="row"><span>${t('cart.delivery')}</span><span>${zl(deliveryFee())}</span></div>` : ''}
    <div class="row row--total"><span>${t('cart.total')}</span><span>${zl(total())}</span></div>
    ${state.cart.length && missing ? `<div class="note">${t('cart.min', { min: zl(R.delivery.minOrder), missing: zl(missing) })}</div>` : ''}
    ${!timeSlots().length ? `<div class="note">${t('cart.closed', { time: R.hours.open })}</div>` : ''}
    <button class="btn btn--primary btn--block btn--lg" id="toCheckout" ${canOrder ? '' : 'disabled'}>${t('cart.checkout')}</button>`;
  $('#cartBar').hidden = !state.cart.length;
  $('#cartBarCount').textContent = count();
  $('#cartBarTotal').textContent = zl(total());
}
const openCart = () => { $('#cart').classList.add('is-open'); $('#backdrop').hidden = false; };
const closeCart = () => { $('#cart').classList.remove('is-open'); $('#backdrop').hidden = true; };

/* ---------- variant modal ---------- */
let vm = null;
function openVariant(p) {
  const g = VARIANT_GROUPS[p.variants];
  vm = { p, qty: 1 };
  $('#vmImg').src = dishImg(p);
  $('#vmName').textContent = nameOf(p);
  $('#vmEn').textContent = altNameOf(p);
  $('#vmLabel').textContent = tx(g.label);
  $('#vmOptions').innerHTML = g.options.map((o, i) =>
    `<label><input type="radio" name="vm" value="${o.id}" ${i === 0 ? 'checked' : ''}> ${nameOf(o)}</label>`).join('');
  renderVm();
  $('#variantModal').hidden = false;
}
function renderVm() {
  $('#vmQty span').textContent = vm.qty;
  $('#vmAdd').textContent = t('vm.add', { price: zl(vm.p.price * vm.qty) });
}

/* ---------- checkout ---------- */
const form = $('#coForm');
function openCheckout() {
  closeCart();
  $('#coError').hidden = true;
  form.classList.remove('was-validated');
  if (!form.city.value) form.city.value = R.address.city.replace(/^\d{2}-\d{3}\s*/, '');
  renderCheckout();
  $('#checkout').hidden = false;
  $('#checkout').scrollTop = 0;
}
function renderCheckout() {
  renderFulfilment();
  const delivery = state.fulfilment === 'delivery';
  $('#coAddress').hidden = !delivery;
  $$('[data-delivery]').forEach(i => { i.required = delivery; });
  $('#coPickupInfo').textContent = delivery
    ? t('co.delivery_info', { fee: zl(R.delivery.fee), eta: eta(R.delivery.eta) })
    : t('co.pickup_info', { address: `${R.address.street}, ${R.address.city}`, eta: eta(R.pickup.eta) });
  $('#coPayOnDelivery').innerHTML = t(delivery ? 'co.pay_delivery' : 'co.pay_pickup');

  const prev = $('#coTime').value;
  const slots = timeSlots();
  const opts = (isOpen() ? [`<option value="asap">${t('co.asap', { eta: eta(delivery ? R.delivery.eta : R.pickup.eta) })}</option>`] : [])
    .concat(slots.map(s => `<option value="${fmt(s)}">${t('co.today_at', { time: fmt(s) })}</option>`));
  $('#coTime').innerHTML = opts.join('');
  if ([...$('#coTime').options].some(o => o.value === prev)) $('#coTime').value = prev;

  const age = hasAlcohol();
  $('#coAgeRow').hidden = !age;
  form.age.required = age;

  const missing = minMissing();
  $('#coSummary').innerHTML = state.cart.map(l => {
    const p = byId(l.pid);
    return `<div class="row"><span>${l.qty}× ${nameOf(p)}${l.variant ? ` <span class="muted">(${variantName(l)})</span>` : ''}</span><span>${zl(p.price * l.qty)}</span></div>`;
  }).join('')
    + (delivery ? `<div class="row"><span>${t('cart.delivery')}</span><span>${zl(R.delivery.fee)}</span></div>` : '')
    + `<div class="row row--total"><span>${t('co.to_pay')}</span><span>${zl(total())}</span></div>`
    + (missing ? `<div class="note" style="margin:.6rem 0 0">${t('cart.min', { min: zl(R.delivery.minOrder), missing: zl(missing) })} ${t('co.min_hint')}</div>` : '');

  const online = form.pay.value === 'online';
  $('#coSubmit').textContent = t(online ? 'co.submit_online' : 'co.submit', { total: zl(total()) });
  $('#coSubmit').disabled = !!missing || !slots.length && !isOpen();
}
// an order whose online payment wasn't confirmed – the customer came back to the form from its page
let pending = null;
function readOrder() {
  const f = Object.fromEntries(new FormData(form));
  return {
    id: pending?.id ?? newOrderId(),
    no: pending?.no ?? newOrderNo(),
    createdAt: pending?.createdAt ?? Date.now(),
    attempt: pending?.attempt ?? 0,
    fulfilment: state.fulfilment,
    time: f.time,
    name: f.name.trim(), phone: f.phone.trim(), email: f.email.trim(),
    address: state.fulfilment === 'delivery' ? `${f.street.trim()}${f.flat ? `/${f.flat.trim()}` : ''}, ${f.postcode} ${f.city.trim()}` : null,
    notes: f.notes.trim(),
    pay: f.pay,
    lines: state.cart.map(l => ({ ...l })),
    fee: deliveryFee(), total: total(),
    lang: LANG,                                  // language of the confirmation e-mail / SMS
    abandonedOnline: (pending?.attempt ?? 0) > 0 && f.pay !== 'online',
    form: f,                                     // lets "Wróć do formularza" on the order page restore the checkout
  };
}
function fillForm(f) {
  Object.entries(f).forEach(([k, v]) => {
    const el = form.elements[k];
    if (el?.type === 'checkbox') el.checked = true; else if (el) el.value = v;
  });
}
function submitOrder(e) {
  e.preventDefault();
  form.classList.add('was-validated');
  if (!form.checkValidity()) {
    $('#coError').textContent = t('co.error');
    $('#coError').hidden = false;
    form.querySelector(':invalid')?.focus();
    return;
  }
  $('#coError').hidden = true;
  pending = readOrder();
  if (pending.pay === 'online') { goToPayment(pending); return; }
  placeOrder(pending);
  location.href = orderUrl(pending);
}

/* ---------- events ---------- */
function setFulfilment(f) { state.fulfilment = f; save(); renderCart(); if (!$('#checkout').hidden) renderCheckout(); }

document.addEventListener('click', e => {
  const step = e.target.closest('[data-step]');
  if (step) { changeQty(`${step.closest('.item').dataset.pid}|`, +step.dataset.step); return; }
  const item = e.target.closest('.item');
  if (item) { const p = byId(item.dataset.pid); p.variants ? openVariant(p) : addToCart(p.id); return; }

  const q = e.target.closest('.qty button[data-key]');
  if (q) { changeQty(q.dataset.key, +q.dataset.d); if (!$('#checkout').hidden) renderCheckout(); return; }

  const f = e.target.closest('[data-f]');
  if (f) { setFulfilment(f.dataset.f); return; }

  if (e.target.closest('#toCheckout')) { openCheckout(); return; }
  if (e.target.closest('#cartBar')) { openCart(); return; }
  if (e.target.closest('#cartClose') || e.target.id === 'backdrop') { closeCart(); return; }

  const m = e.target.closest('[data-modal]');
  if (m) { e.preventDefault(); $('#termsModal').hidden = false; return; }

  if (e.target.closest('[data-close]') || e.target.classList.contains('modal')) { e.target.closest('.modal').hidden = true; return; }
});

$('#vmQty').addEventListener('click', e => {
  const b = e.target.closest('button'); if (!b) return;
  vm.qty = Math.max(1, vm.qty + +b.dataset.d); renderVm();
});
$('#vmAdd').addEventListener('click', () => {
  addToCart(vm.p.id, $('#vmOptions input:checked').value, vm.qty);
  $('#variantModal').hidden = true;
});

form.addEventListener('submit', submitOrder);
form.addEventListener('change', e => { if (e.target.name === 'pay') renderCheckout(); });

$$('.lang select').forEach(s => s.addEventListener('change', e => setLang(e.target.value)));
// once the header pill slides under the sticky bar, show the compact one there
new IntersectionObserver(([e]) => $('#cats').classList.toggle('has-lang', !e.isIntersecting), { rootMargin: '-56px 0px 0px 0px' })
  .observe($('#langHeader'));
document.addEventListener('keydown', e => {
  if (e.key !== 'Escape') return;
  ['#variantModal', '#termsModal', '#checkout'].forEach(s => { $(s).hidden = true; });
  closeCart();
});

applyI18n();
renderLang();
renderHeader();
renderOrderLink();
renderMenu();
renderCart();
setupScrollSpy();

// index.html?edit=<id> – "Wróć do formularza" on the order page: reopen the checkout for the same order
const editing = orders.get(new URLSearchParams(location.search).get('edit'));
if (editing) {
  history.replaceState(null, '', location.pathname);
  if (isPlaced(editing)) location.replace(orderUrl(editing));
  else { pending = editing; setFulfilment(editing.fulfilment); openCheckout(); fillForm(editing.form); renderCheckout(); }
}
